// DFS 淹沒法：遇到陸地就計數，並把整座島改成 '0'
// 時間複雜度: O(m·n)，空間複雜度: O(m·n)（最壞遞迴深度）
function numIslands(grid) {
    const m = grid.length, n = grid[0].length;
    const sink = (i, j) => {
        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== '1')
            return;
        grid[i][j] = '0';
        sink(i + 1, j);
        sink(i - 1, j);
        sink(i, j + 1);
        sink(i, j - 1);
    };
    let count = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === '1') {
                count++;
                sink(i, j);
            }
        }
    }
    return count;
}

