#include <vector>
#include <queue>

class Solution {
public:
    /**
     * 方法一：DFS（推薦）
     * 時間複雜度: O(m × n)
     * 空間複雜度: O(m × n)
     */
    int numIslands(std::vector<std::vector<char>>& grid) {
        if (grid.empty() || grid[0].empty()) {
            return 0;
        }

        int rows = grid.size();
        int cols = grid[0].size();
        int count = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '1') {
                    count++;
                    dfs(grid, r, c);
                }
            }
        }

        return count;
    }

private:
    void dfs(std::vector<std::vector<char>>& grid, int r, int c) {
        int rows = grid.size();
        int cols = grid[0].size();

        // 邊界檢查和水域檢查
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '0') {
            return;
        }

        // 標記當前陸地為已訪問
        grid[r][c] = '0';

        // 遞迴訪問四個方向
        dfs(grid, r + 1, c);  // 下
        dfs(grid, r - 1, c);  // 上
        dfs(grid, r, c + 1);  // 右
        dfs(grid, r, c - 1);  // 左
    }

public:
    /**
     * 方法二：BFS
     * 時間複雜度: O(m × n)
     * 空間複雜度: O(min(m, n))
     */
    int numIslands_bfs(std::vector<std::vector<char>>& grid) {
        if (grid.empty() || grid[0].empty()) {
            return 0;
        }

        int rows = grid.size();
        int cols = grid[0].size();
        int count = 0;

        for (int r = 0; r < rows; r++) {
            for (c = 0; c < cols; c++) {
                if (grid[r][c] == '1') {
                    count++;
                    bfs(grid, r, c);
                }
            }
        }

        return count;
    }

private:
    void bfs(std::vector<std::vector<char>>& grid, int r, int c) {
        int rows = grid.size();
        int cols = grid[0].size();

        std::queue<std::pair<int, int>> queue;
        queue.push({r, c});
        grid[r][c] = '0';

        int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.empty()) {
            auto [row, col] = queue.front();
            queue.pop();

            for (auto& dir : directions) {
                int nr = row + dir[0];
                int nc = col + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && 
                    grid[nr][nc] == '1') {
                    grid[nr][nc] = '0';
                    queue.push({nr, nc});
                }
            }
        }
    }
};

