// DFS 淹沒法：遇到陸地就計數，並把整座島改成 '0'
// 時間複雜度: O(m·n)，空間複雜度: O(m·n)（最壞遞迴深度）
static void sink(char** grid, int m, int n, int i, int j) {
    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != '1') return;
    grid[i][j] = '0';
    sink(grid, m, n, i + 1, j);
    sink(grid, m, n, i - 1, j);
    sink(grid, m, n, i, j + 1);
    sink(grid, m, n, i, j - 1);
}

int numIslands(char** grid, int gridSize, int* gridColSize) {
    int m = gridSize, n = gridColSize[0], count = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == '1') {
                count++;
                sink(grid, m, n, i, j);
            }
        }
    }
    return count;
}
